import { getAuthUser, getPermissionsCacheEntry } from '@linm-soft-org/linm-web-common-components';
import { isPermissionsLocalModeActive } from '../dev/isPermissionsLocalMode';

const FULL_LIST_PACKAGE_CODES = ['MANAGER', 'ADMIN'] as const;

export function readCachedPermissionCodes(): string[] {
  const payload = getPermissionsCacheEntry()?.payload;
  const codes = payload?.permissionCodes;
  if (!Array.isArray(codes)) return [];
  return codes.filter((c): c is string => typeof c === 'string' && c.length > 0);
}

export function readCachedPackageCodes(): string[] {
  const payload = getPermissionsCacheEntry()?.payload;
  const codes = payload?.packageCodes;
  if (!Array.isArray(codes)) return [];
  return codes.filter((c): c is string => typeof c === 'string' && c.length > 0);
}

function hasManagerOrAdminRole(): boolean {
  const role = getAuthUser()?.role?.toLowerCase();
  return role === 'manager' || role === 'admin';
}

function hasManagerOrAdminPackage(): boolean {
  return readCachedPackageCodes().some((code) =>
    FULL_LIST_PACKAGE_CODES.some(
      (p) => p.localeCompare(code, undefined, { sensitivity: 'accent' }) === 0,
    ),
  );
}

export function hasPermissionCode(code: string): boolean {
  if (isPermissionsLocalModeActive()) return true;
  const target = code.trim();
  if (!target) return false;
  return readCachedPermissionCodes().some(
    (c) => c.localeCompare(target, undefined, { sensitivity: 'accent' }) === 0,
  );
}

/** Full org incident list — not reporter scope (parity BE ResolveReporterScopeCreatedByIdAsync). */
export function hasFullIncidentListAccess(flags: {
  canStartAnalysis: boolean;
  canSaveAnalysis: boolean;
  canCompleteAnalysis: boolean;
  canEditWhenComplete: boolean;
  canBatchStatus: boolean;
  canImport: boolean;
}): boolean {
  if (isPermissionsLocalModeActive()) return true;
  if (hasManagerOrAdminRole() || hasManagerOrAdminPackage()) return true;
  return (
    flags.canStartAnalysis
    || flags.canSaveAnalysis
    || flags.canCompleteAnalysis
    || flags.canEditWhenComplete
    || flags.canBatchStatus
    || flags.canImport
  );
}
