import React from 'react';
import styles from './ReportPageSkeleton.module.css';

/** Heights (%) for the 12 fake bar columns — vary them so it looks realistic */
const BAR_HEIGHTS = [40, 70, 55, 90, 35, 75, 50, 65, 80, 45, 60, 85];

/** Widths for 5 fake tab pills */
const TAB_WIDTHS = ['80px', '120px', '100px', '90px', '140px'];

/**
 * ReportPageSkeleton
 * Displayed while the report API call is in flight.
 * Mimics the Tabs bar + bar-chart content area so the layout doesn't jump.
 */
export const ReportPageSkeleton: React.FC = () => (
  <div className={styles.root}>

    {/* ── Tab bar ───────────────────────────────────────────────────── */}
    <div className={styles.tabBar}>
      {TAB_WIDTHS.map((w, i) => (
        <div key={i} className={styles.tabPill} style={{ width: w }} />
      ))}
    </div>

    {/* ── Chart body ────────────────────────────────────────────────── */}
    <div className={styles.chartArea}>
      <div className={styles.chartBody}>
        {BAR_HEIGHTS.map((h, i) => (
          <div
            key={i}
            className={styles.bar}
            style={{ height: `${h}%` }}
          />
        ))}
      </div>
      <div className={styles.xAxis} />
      <div className={styles.xLabels}>
        {BAR_HEIGHTS.map((_, i) => (
          <div key={i} className={styles.xLabel} />
        ))}
      </div>
    </div>

    {/* ── Bottom text lines ─────────────────────────────────────────── */}
    <div className={styles.textLines}>
      <div className={styles.textLine} style={{ width: '60%' }} />
      <div className={styles.textLine} style={{ width: '40%' }} />
      <div className={styles.textLine} style={{ width: '50%' }} />
    </div>

  </div>
);
